window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f87ab5fa43a9f323"]={"versions": [{"id": "FIG-f87ab5fa43a9f323", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzmodell/M1-Ebene) im Kontext der AUTOSAR-Werkzeug-Interoperabilität (Modellaustausch und Modell-Differenzierung/Merging). Dargestellt ist eine Instanzstruktur zur Demonstration einer Element-Umbenennung (<code>ApplicationPrimitiveDataType</code> mit dem neuen Bezeichner <code>speedType</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält folgende Instanzen (Objekte) und Relationen:</p>\n<ul class=\"fig-list\"><li><code>:ARPackage</code> (shortName = &quot;OEM&quot;) enthält über die Kompositionsrolle <code>+element</code> zwei Elemente:\n<ul class=\"fig-list\"><li><code>:ApplicationPrimitiveDataType</code> (shortName = &quot;speedType&quot;)\n</li><li><code>:SenderReceiverInterface</code> (shortName = &quot;interface&quot;, isService = false)\n</li></ul>\n</li><li><code>:SenderReceiverInterface</code> aggregiert/komponiert über die Rolle <code>+dataElement</code>:\n<ul class=\"fig-list\"><li><code>:VariableDataPrototype</code> (shortName = &quot;velocity&quot;)\n</li></ul>\n</li><li><code>:VariableDataPrototype</code> referenziert über die Assoziation <code>+type</code>:\n<ul class=\"fig-list\"><li><code>:ApplicationPrimitiveDataType</code> (shortName = &quot;speedType&quot;)\n</li></ul>\n</li><li><code>:ApplicationPrimitiveDataType</code> besitzt über Kompositionsbeziehungen:\n<ul class=\"fig-list\"><li><code>+invalidValue</code>: <code>:NumericalValueSpecification</code> (value = 10000)\n</li><li><code>+displayFormat</code>: <code>:DisplayFormatString</code> (value = &quot;%f6.2&quot;)\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Grün hinterlegte Boxen kennzeichnen im Kontext des Diff-Beispiels modifizierte Elemente bzw. betroffene Pfade (<code>:ARPackage</code>, <code>:ApplicationPrimitiveDataType</code>, <code>:VariableDataPrototype</code>).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Objekt-/Instanzmodell; kein dynamischer Sequenzablauf vorhanden. Dargestellt wird der statische Zustand eines ARXML-Datenmodells nach Modifikation (Umbenennung eines referenzierten Datentyps von ehemals <code>velocityType</code> zu <code>speedType</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als normatives/illustrierendes Beispielszenario für AUTOSAR-Tools beim Modellvergleich und Modellaustausch. Werkzeuge müssen erkennen, dass eine Umbenennung des Datentyps (<code>speedType</code>) Auswirkungen auf typisierende Referenzen (<code>+type</code> ausgehend vom <code>VariableDataPrototype</code>) hat, während die Referenzstruktur intakt bleibt. Ferner sind Kind-Elemente (<code>NumericalValueSpecification</code>, <code>DisplayFormatString</code>) semantisch an den umbenannten Datentyp gebunden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f7c6b98617066e44", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzmodell/M1-Ebene) im Kontext der AUTOSAR-Werkzeug-Interoperabilität (Modellaustausch und Modell-Differenzierung/Merging). Dargestellt ist eine Instanzstruktur zur Demonstration einer Element-Umbenennung (<code>ApplicationPrimitiveDataType</code> mit dem neuen Bezeichner <code>speedType</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält folgende Instanzen (Objekte) und Relationen:</p>\n<ul class=\"fig-list\"><li><code>:ARPackage</code> (shortName = &quot;OEM&quot;) enthält über die Kompositionsrolle <code>+element</code> zwei Elemente:\n<ul class=\"fig-list\"><li><code>:ApplicationPrimitiveDataType</code> (shortName = &quot;speedType&quot;)\n</li><li><code>:SenderReceiverInterface</code> (shortName = &quot;interface&quot;, isService = false)\n</li></ul>\n</li><li><code>:SenderReceiverInterface</code> aggregiert/komponiert über die Rolle <code>+dataElement</code>:\n<ul class=\"fig-list\"><li><code>:VariableDataPrototype</code> (shortName = &quot;velocity&quot;)\n</li></ul>\n</li><li><code>:VariableDataPrototype</code> referenziert über die Assoziation <code>+type</code>:\n<ul class=\"fig-list\"><li><code>:ApplicationPrimitiveDataType</code> (shortName = &quot;speedType&quot;)\n</li></ul>\n</li><li><code>:ApplicationPrimitiveDataType</code> besitzt über Kompositionsbeziehungen:\n<ul class=\"fig-list\"><li><code>+invalidValue</code>: <code>:NumericalValueSpecification</code> (value = 10000)\n</li><li><code>+displayFormat</code>: <code>:DisplayFormatString</code> (value = &quot;%f6.2&quot;)\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Grün hinterlegte Boxen kennzeichnen im Kontext des Diff-Beispiels modifizierte Elemente bzw. betroffene Pfade (<code>:ARPackage</code>, <code>:ApplicationPrimitiveDataType</code>, <code>:VariableDataPrototype</code>).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Objekt-/Instanzmodell; kein dynamischer Sequenzablauf vorhanden. Dargestellt wird der statische Zustand eines ARXML-Datenmodells nach Modifikation (Umbenennung eines referenzierten Datentyps von ehemals <code>velocityType</code> zu <code>speedType</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als normatives/illustrierendes Beispielszenario für AUTOSAR-Tools beim Modellvergleich und Modellaustausch. Werkzeuge müssen erkennen, dass eine Umbenennung des Datentyps (<code>speedType</code>) Auswirkungen auf typisierende Referenzen (<code>+type</code> ausgehend vom <code>VariableDataPrototype</code>) hat, während die Referenzstruktur intakt bleibt. Ferner sind Kind-Elemente (<code>NumericalValueSpecification</code>, <code>DisplayFormatString</code>) semantisch an den umbenannten Datentyp gebunden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-f87ab5fa43a9f323", "to": "FIG-f7c6b98617066e44", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
